func removeSemanticArtifactsKeepingLock(brainDir string) error {
	semanticPath := filepath.Join(brainDir, semanticDirName)
	entries, err := os.ReadDir(semanticPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for _, entry := range entries {
		if entry.Name() == semanticLockDir {
			continue
		}
		rel := filepath.Join(semanticDirName, entry.Name())
		if err := rejectSymlinkPathComponents(brainDir, rel); err != nil {
			return err
		}
		if err := os.RemoveAll(filepath.Join(semanticPath, entry.Name())); err != nil {
			return err
		}
	}
	return nil
}

