			}
			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
			return renderedCommandError{err: err}
		}
	}
	if cmd.RunE != nil {
		run := cmd.RunE
		cmd.RunE = func(cmd *cobra.Command, args []string) error {
			err := run(cmd, args)
			if err == nil || !commandWantsJSONError(cmd) {
				return err
			}
			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
			return renderedCommandError{err: err}
