		case "file":
			if path := record.semanticPath(); path != "" {
				files[path] = struct{}{}
			}
		case "symbol":
			if path := record.semanticPath(); path != "" {
				files[path] = struct{}{}
			}
			counts.Symbols++
		case "relation":
			counts.Relations++
		}
